begin;
create extension if not exists pgtap with schema extensions;
select plan(13);
select has_column('public','attachments','document_kind','attachments classify approved quotations');
select has_function('public','approve_quotation_attachment',array['uuid','uuid'],'quotation approval transaction exists');
select ok(not has_function_privilege('anon','public.approve_quotation_attachment(uuid,uuid)','execute'),'anon cannot approve quotations');

insert into public.organizations(id,name,slug,reference_prefix) values('a1000000-0000-4000-8000-000000000001','Lifecycle A','lifecycle-a','LA'),('a1000000-0000-4000-8000-000000000002','Lifecycle B','lifecycle-b','LB');
insert into public.departments(id,organization_id,name) values('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','Commercial'),('a2000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','Commercial');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values('a3000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','manager-a@example.test','',now(),now()),('a3000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','manager-b@example.test','',now(),now());
insert into public.organization_members(id,organization_id,user_id,role,department_id,display_name) values('a4000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','manager','a2000000-0000-4000-8000-000000000001','Manager A'),('a4000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','a3000000-0000-4000-8000-000000000002','manager','a2000000-0000-4000-8000-000000000002','Manager B');
insert into public.services(id,organization_id,department_id,name) values('a5000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','Construction'),('a5000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','a2000000-0000-4000-8000-000000000002','Construction');
insert into public.customers(id,organization_id,full_name) values('a6000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','Customer A');
insert into public.requests(id,organization_id,customer_id,service_id,department_id,assigned_member_id,reference_number,request_type,status,title,description,location,idempotency_key,confirmed_at) values('a7000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001',null,'quotation','quotation_preparing','Quote','Quote request','Yaounde','a8000000-0000-4000-8000-000000000001',now());
insert into public.attachments(id,organization_id,request_id,storage_bucket,storage_path,original_filename,mime_type,size_bytes,uploaded_by_member_id,uploaded_by_type,upload_status,scan_status,content_sha256,completed_at) values('a9000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','private-attachments','a1000000-0000-4000-8000-000000000001/request/a7000000-0000-4000-8000-000000000001/a9000000-0000-4000-8000-000000000001.pdf','quote.pdf','application/pdf',100,'a4000000-0000-4000-8000-000000000001','employee','active','clean',repeat('a',64),now()),('a9000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','private-attachments','a1000000-0000-4000-8000-000000000001/request/a7000000-0000-4000-8000-000000000001/a9000000-0000-4000-8000-000000000002.png','photo.png','image/png',100,'a4000000-0000-4000-8000-000000000001','employee','active','clean',repeat('b',64),now());
set local role authenticated;
select set_config('request.jwt.claim.sub','a3000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.transition_request_status('a7000000-0000-4000-8000-000000000001','quotation_sent',null,(select updated_at from public.requests where id='a7000000-0000-4000-8000-000000000001'))$$,'23514',null,'quotation cannot be sent without approval');
select throws_ok($$select public.approve_quotation_attachment('a7000000-0000-4000-8000-000000000001','a9000000-0000-4000-8000-000000000002')$$,'23514',null,'non-PDF cannot be approved');
select lives_ok($$select public.approve_quotation_attachment('a7000000-0000-4000-8000-000000000001','a9000000-0000-4000-8000-000000000001')$$,'authorized manager approves PDF');
select is((select document_kind from public.attachments where id='a9000000-0000-4000-8000-000000000001'),'quotation','attachment records quotation classification');
select is((select count(*) from public.audit_events where action='request.quotation_approved'),1::bigint,'approval is audited');
select lives_ok($$select public.transition_request_status('a7000000-0000-4000-8000-000000000001','quotation_sent',null,(select updated_at from public.requests where id='a7000000-0000-4000-8000-000000000001'))$$,'approved quotation permits sent status');
select is((select status from public.requests where id='a7000000-0000-4000-8000-000000000001'),'quotation_sent','request reaches quotation sent');
select throws_ok($$select public.transition_request_status('a7000000-0000-4000-8000-000000000001','quotation_accepted',null,(select updated_at from public.requests where id='a7000000-0000-4000-8000-000000000001'))$$,'23514',null,'acceptance requires provenance');
select lives_ok($$select public.transition_request_status('a7000000-0000-4000-8000-000000000001','quotation_accepted','Customer accepted by signed email',(select updated_at from public.requests where id='a7000000-0000-4000-8000-000000000001'))$$,'acceptance with provenance succeeds');
select set_config('request.jwt.claim.sub','a3000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.approve_quotation_attachment('a7000000-0000-4000-8000-000000000001','a9000000-0000-4000-8000-000000000001')$$,'P0002',null,'other tenant cannot approve quotation');
select * from finish();
rollback;
